/* ============================================
   Orchard — Premium Tech E-Commerce Styles
   ============================================ */

/* CSS Variables */
:root {
  --color-bg: #ffffff;
  --color-bg-secondary: #f5f5f7;
  --color-text: #1d1d1f;
  --color-text-secondary: #6e6e73;
  --color-link: #0066cc;
  --color-link-hover: #0077ed;
  --color-border: #d2d2d7;
  --color-badge: #ff3b30;
  --color-badge-bg: #fff0f0;
  --font-stack: -apple-system, BlinkMacSystemFont, "SF Pro Display", "SF Pro Text", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --max-width: 1024px;
  --section-padding: 48px;
  --card-radius: 18px;
  --transition: 0.25s ease;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-stack);
  color: var(--color-text);
  background: var(--color-bg);
  line-height: 1.47059;
  font-weight: 400;
  letter-spacing: -0.022em;
}

a {
  color: var(--color-link);
  text-decoration: none;
  transition: color var(--transition);
}

a:hover {
  color: var(--color-link-hover);
  text-decoration: underline;
}

img {
  max-width: 100%;
  display: block;
}

ul, ol {
  list-style: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* ============================================
   Layout Utilities
   ============================================ */

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.section {
  padding: var(--section-padding) 0;
}

.section-bg {
  background: var(--color-bg-secondary);
}

.section-header {
  text-align: center;
  margin-bottom: 32px;
}

.section-header h2 {
  font-size: 40px;
  font-weight: 600;
  letter-spacing: -0.003em;
  line-height: 1.1;
}

.section-header p {
  font-size: 21px;
  color: var(--color-text-secondary);
  margin-top: 8px;
  font-weight: 400;
}

/* ============================================
   Navigation
   ============================================ */

.main-nav {
  background: rgba(255,255,255,0.8);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid rgba(0,0,0,0.05);
  position: sticky;
  top: 0;
  z-index: 1000;
}

.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 48px;
}

.nav-logo {
  font-size: 20px;
  font-weight: 600;
  color: var(--color-text);
  text-decoration: none;
}

.nav-logo:hover {
  text-decoration: none;
}

.nav-links {
  display: flex;
  gap: 28px;
}

.nav-links a {
  font-size: 12px;
  color: var(--color-text);
  opacity: 0.8;
  text-decoration: none;
  transition: opacity var(--transition);
}

.nav-links a:hover {
  opacity: 1;
  text-decoration: none;
}

/* ============================================
   Ribbon Banner
   ============================================ */

.ribbon {
  background: var(--color-bg-secondary);
  text-align: center;
  padding: 12px 24px;
  font-size: 14px;
}

.ribbon a {
  color: var(--color-link);
}

/* ============================================
   Hero
   ============================================ */

.hero {
  text-align: center;
  padding: 60px 24px 40px;
}

.hero h1 {
  font-size: 48px;
  font-weight: 600;
  letter-spacing: -0.003em;
  line-height: 1.08349;
}

.hero p {
  font-size: 21px;
  color: var(--color-text-secondary);
  margin-top: 12px;
}

.hero-links {
  margin-top: 20px;
  display: flex;
  gap: 24px;
  justify-content: center;
  font-size: 17px;
}

.hero-links a {
  color: var(--color-link);
}

.hero-links a::after {
  content: " ›";
}

/* ============================================
   Product Icon Bar
   ============================================ */

.icon-bar {
  display: flex;
  gap: 32px;
  justify-content: center;
  flex-wrap: wrap;
  padding: 24px 0;
}

.icon-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: var(--color-text);
  text-decoration: none;
  min-width: 64px;
}

.icon-item:hover {
  text-decoration: none;
}

.icon-circle {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--color-bg-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  transition: transform var(--transition);
}

.icon-item:hover .icon-circle {
  transform: scale(1.08);
}

/* ============================================
   Carousels
   ============================================ */

.carousel-wrapper {
  position: relative;
  overflow: hidden;
}

.carousel {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 8px 24px 32px;
}

.carousel::-webkit-scrollbar {
  display: none;
}

.carousel-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,0.9);
  box-shadow: 0 2px 8px rgba(0,0,0,0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  color: var(--color-text);
  cursor: pointer;
  z-index: 10;
  transition: opacity var(--transition), transform var(--transition);
  opacity: 0.7;
}

.carousel-nav:hover {
  opacity: 1;
  transform: translateY(-50%) scale(1.1);
}

.carousel-nav.prev { left: 8px; }
.carousel-nav.next { right: 8px; }

.carousel-nav.hidden {
  opacity: 0;
  pointer-events: none;
}

/* ============================================
   Product Cards
   ============================================ */

.product-card {
  flex: 0 0 320px;
  scroll-snap-align: start;
  background: var(--color-bg);
  border-radius: var(--card-radius);
  overflow: hidden;
  box-shadow: 0 4px 16px rgba(0,0,0,0.06);
  transition: transform var(--transition), box-shadow var(--transition);
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 24px rgba(0,0,0,0.1);
}

.card-image {
  height: 220px;
  background: var(--color-bg-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 64px;
  position: relative;
}

.card-badge {
  position: absolute;
  top: 16px;
  left: 16px;
  background: var(--color-badge-bg);
  color: var(--color-badge);
  font-size: 11px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 12px;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.card-content {
  padding: 20px;
}

.card-content h3 {
  font-size: 21px;
  font-weight: 600;
  line-height: 1.19048;
}

.card-content .tagline {
  font-size: 14px;
  color: var(--color-text-secondary);
  margin-top: 4px;
}

.card-content .price {
  font-size: 15px;
  margin-top: 12px;
}

.card-content .monthly {
  font-size: 13px;
  color: var(--color-text-secondary);
  margin-top: 2px;
}

.card-actions {
  display: flex;
  gap: 20px;
  margin-top: 16px;
  font-size: 14px;
}

.card-actions a:first-child {
  color: var(--color-link);
}

.card-actions a:last-child {
  color: var(--color-link);
}

/* ============================================
   Hero Product Grid (Homepage)
   ============================================ */

.product-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
  padding: 0 16px 48px;
  max-width: 1200px;
  margin: 0 auto;
}

.hero-tile {
  background: var(--color-bg-secondary);
  border-radius: var(--card-radius);
  text-align: center;
  padding: 48px 24px;
  min-height: 480px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  position: relative;
  overflow: hidden;
  transition: transform var(--transition);
}

.hero-tile:hover {
  transform: scale(1.01);
}

.hero-tile.dark {
  background: #000000;
  color: #fff;
}

.hero-tile.dark p {
  color: #a1a1a6;
}

.hero-tile.dark a {
  color: #2997ff;
}

.hero-tile h3 {
  font-size: 32px;
  font-weight: 600;
  letter-spacing: -0.003em;
}

.hero-tile p {
  font-size: 17px;
  color: var(--color-text-secondary);
  margin-top: 8px;
}

.hero-tile .tile-links {
  display: flex;
  gap: 24px;
  margin-top: 16px;
  font-size: 15px;
}

.hero-tile .tile-links a::after {
  content: " ›";
}

.tile-image {
  margin-top: auto;
  font-size: 120px;
  line-height: 1;
  padding-top: 24px;
}

/* ============================================
   Entertainment Tabs
   ============================================ */

.entertainment-tabs {
  display: flex;
  justify-content: center;
  gap: 32px;
  margin-bottom: 32px;
  border-bottom: 1px solid var(--color-border);
  padding: 0 24px;
}

.entertainment-tabs button {
  font-size: 17px;
  padding: 12px 4px;
  color: var(--color-text-secondary);
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  transition: color var(--transition), border-color var(--transition);
}

.entertainment-tabs button.active {
  color: var(--color-text);
  border-bottom-color: var(--color-text);
}

.entertainment-tabs button:hover {
  color: var(--color-text);
}

.entertainment-panels {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.entertainment-panel {
  display: none;
}

.entertainment-panel.active {
  display: block;
}

.entertainment-panel .carousel {
  padding-left: 0;
  padding-right: 0;
}

.entertainment-card {
  flex: 0 0 380px;
  scroll-snap-align: start;
  border-radius: var(--card-radius);
  overflow: hidden;
  position: relative;
  height: 240px;
  background: #333;
  color: #fff;
}

.entertainment-card .card-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 24px;
  background: linear-gradient(transparent, rgba(0,0,0,0.7));
}

.entertainment-card h4 {
  font-size: 21px;
  font-weight: 600;
}

.entertainment-card p {
  font-size: 14px;
  opacity: 0.9;
  margin-top: 4px;
}

.entertainment-card a {
  display: inline-block;
  margin-top: 12px;
  font-size: 14px;
  color: #fff;
  text-decoration: underline;
}

/* ============================================
   Help / Difference / Guide Cards
   ============================================ */

.info-card {
  flex: 0 0 300px;
  scroll-snap-align: start;
  background: var(--color-bg);
  border-radius: var(--card-radius);
  padding: 32px;
  box-shadow: 0 4px 16px rgba(0,0,0,0.06);
  text-align: center;
}

.info-card .card-icon {
  font-size: 48px;
  margin-bottom: 16px;
}

.info-card h4 {
  font-size: 17px;
  font-weight: 600;
}

.info-card p {
  font-size: 14px;
  color: var(--color-text-secondary);
  margin-top: 8px;
  line-height: 1.4;
}

/* ============================================
   Quick Links
   ============================================ */

.quick-links {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
  padding: 24px;
}

.quick-links a {
  display: inline-block;
  padding: 10px 20px;
  border-radius: 20px;
  background: var(--color-bg-secondary);
  color: var(--color-text);
  font-size: 14px;
  text-decoration: none;
  transition: background var(--transition);
}

.quick-links a:hover {
  background: var(--color-border);
  text-decoration: none;
}

/* ============================================
   Category Pages — Sticky Section Nav
   ============================================ */

.section-nav {
  position: sticky;
  top: 48px;
  background: rgba(255,255,255,0.9);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid rgba(0,0,0,0.05);
  z-index: 900;
  overflow-x: auto;
  scrollbar-width: none;
}

.section-nav::-webkit-scrollbar {
  display: none;
}

.section-nav-inner {
  display: flex;
  gap: 32px;
  justify-content: center;
  padding: 12px 24px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.section-nav a {
  font-size: 14px;
  color: var(--color-text);
  opacity: 0.8;
  white-space: nowrap;
  text-decoration: none;
}

.section-nav a:hover {
  opacity: 1;
  text-decoration: none;
}

/* ============================================
   Brand Collaboration
   ============================================ */

.brand-collab {
  background: linear-gradient(135deg, #f5f5f7 0%, #e8e8ed 100%);
  text-align: center;
  padding: 64px 24px;
}

.brand-collab h2 {
  font-size: 40px;
  font-weight: 600;
}

.brand-collab p {
  font-size: 17px;
  color: var(--color-text-secondary);
  margin-top: 12px;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

/* ============================================
   Footer
   ============================================ */

.footer {
  background: var(--color-bg-secondary);
  padding: 40px 0 24px;
  font-size: 12px;
  color: var(--color-text-secondary);
}

.footer-grid {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.footer-col h4 {
  font-size: 12px;
  font-weight: 600;
  color: var(--color-text);
  margin-bottom: 12px;
}

.footer-col ul li {
  margin-bottom: 8px;
}

.footer-col ul li a {
  color: var(--color-text-secondary);
  text-decoration: none;
}

.footer-col ul li a:hover {
  color: var(--color-text);
  text-decoration: underline;
}

.footer-legal {
  max-width: var(--max-width);
  margin: 24px auto 0;
  padding: 24px 24px 0;
  border-top: 1px solid var(--color-border);
}

.footer-legal p {
  margin-bottom: 8px;
}

/* ============================================
   Mobile Footer Accordion
   ============================================ */

.footer-col h4 {
  pointer-events: none;
}

@media (max-width: 768px) {
  .footer-grid {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .footer-col {
    border-bottom: 1px solid var(--color-border);
  }

  .footer-col h4 {
    pointer-events: auto;
    padding: 12px 0;
    margin-bottom: 0;
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: pointer;
  }

  .footer-col h4::after {
    content: "+";
    font-size: 16px;
    transition: transform var(--transition);
  }

  .footer-col.open h4::after {
    content: "−";
  }

  .footer-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height var(--transition);
  }

  .footer-col.open ul {
    max-height: 400px;
    padding-bottom: 12px;
  }
}

/* ============================================
   Responsive
   ============================================ */

@media (max-width: 768px) {
  .product-grid {
    grid-template-columns: 1fr;
  }

  .hero h1 {
    font-size: 32px;
  }

  .section-header h2 {
    font-size: 28px;
  }

  .nav-links {
    gap: 16px;
  }

  .carousel-nav {
    display: none;
  }

  .section-nav-inner {
    justify-content: flex-start;
  }
}

@media (max-width: 1024px) {
  .hero-tile {
    min-height: 400px;
  }
}

/* ============================================
   Orchard — Shared Scripts
   ============================================ */

(function () {
  'use strict';

  /* ---------- Carousel Logic ---------- */
  function initCarousels() {
    document.querySelectorAll('.carousel-wrapper').forEach(function (wrapper) {
      const carousel = wrapper.querySelector('.carousel');
      const prevBtn = wrapper.querySelector('.carousel-nav.prev');
      const nextBtn = wrapper.querySelector('.carousel-nav.next');
      if (!carousel) return;

      function updateButtons() {
        if (prevBtn) {
          prevBtn.classList.toggle('hidden', carousel.scrollLeft <= 1);
        }
        if (nextBtn) {
          const maxScroll = carousel.scrollWidth - carousel.clientWidth;
          nextBtn.classList.toggle('hidden', carousel.scrollLeft >= maxScroll - 1);
        }
      }

      function scrollByCard(direction) {
        const card = carousel.querySelector('.product-card, .info-card, .entertainment-card');
        const gap = 20;
        const amount = card ? (card.offsetWidth + gap) * direction : 340 * direction;
        carousel.scrollBy({ left: amount, behavior: 'smooth' });
      }

      if (prevBtn) prevBtn.addEventListener('click', function () { scrollByCard(-1); });
      if (nextBtn) nextBtn.addEventListener('click', function () { scrollByCard(1); });

      carousel.addEventListener('scroll', updateButtons, { passive: true });
      // initial state
      window.addEventListener('load', updateButtons);
      updateButtons();
    });
  }

  /* ---------- Entertainment Tabs ---------- */
  function initEntertainmentTabs() {
    const tabContainer = document.querySelector('.entertainment-tabs');
    if (!tabContainer) return;

    const tabs = tabContainer.querySelectorAll('button');
    const panels = document.querySelectorAll('.entertainment-panel');

    tabs.forEach(function (tab) {
      tab.addEventListener('click', function () {
        const target = tab.dataset.tab;
        tabs.forEach(function (t) { t.classList.remove('active'); });
        tab.classList.add('active');
        panels.forEach(function (p) {
          p.classList.toggle('active', p.dataset.panel === target);
        });
      });
    });
  }

  /* ---------- Footer Accordion (mobile) ---------- */
  function initFooterAccordion() {
    const cols = document.querySelectorAll('.footer-col');
    const mql = window.matchMedia('(max-width: 768px)');

    function toggleCol(e) {
      if (!mql.matches) return;
      const col = e.currentTarget.closest('.footer-col');
      col.classList.toggle('open');
    }

    cols.forEach(function (col) {
      const heading = col.querySelector('h4');
      if (heading) {
        heading.addEventListener('click', toggleCol);
      }
    });

    // Reset on resize to desktop
    mql.addEventListener('change', function (e) {
      if (!e.matches) {
        cols.forEach(function (col) { col.classList.remove('open'); });
      }
    });
  }

  /* ---------- Section Nav Active State ---------- */
  function initSectionNav() {
    const nav = document.querySelector('.section-nav');
    if (!nav) return;
    const links = nav.querySelectorAll('a[href^="#"]');
    const sections = [];
    links.forEach(function (link) {
      const id = link.getAttribute('href').slice(1);
      const section = document.getElementById(id);
      if (section) sections.push({ link: link, section: section });
    });

    const observer = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          sections.forEach(function (s) {
            s.link.style.opacity = s.section === entry.target ? '1' : '0.6';
          });
        }
      });
    }, { rootMargin: '-40% 0px -55% 0px', threshold: 0 });

    sections.forEach(function (s) { observer.observe(s.section); });
  }

  /* ---------- Init ---------- */
  document.addEventListener('DOMContentLoaded', function () {
    initCarousels();
    initEntertainmentTabs();
    initFooterAccordion();
    initSectionNav();
  });
})();
